-- Rentals Phase 49: mobile-ready inspection execution; templates/scheduling remain Phase 48.
begin;
create table public.rental_field_inspections(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),property_id uuid not null references public.rental_properties(id),unit_id uuid not null references public.rental_units(id),tenancy_id uuid references public.rental_tenancies(id),inspection_type text not null check(inspection_type in('incoming','routine','outgoing','maintenance_follow_up')),status text not null default 'in_progress' check(status in('in_progress','completed')),started_by uuid not null references auth.users(id),started_at timestamptz not null default now(),completed_by uuid references auth.users(id),completed_at timestamptz,acknowledged_by_name text,signature_evidence_link text,summary_note text);
create table public.rental_field_inspection_items(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references public.rental_field_inspections(id),item_key text not null,item_label text not null,status text not null default 'not_checked' check(status in('not_checked','pass','attention','not_applicable')),note text,evidence_link text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(inspection_id,item_key));
create index rental_field_inspections_unit_idx on public.rental_field_inspections(unit_id,status,started_at desc);alter table public.rental_field_inspections enable row level security;alter table public.rental_field_inspection_items enable row level security;revoke all on public.rental_field_inspections,public.rental_field_inspection_items from anon,authenticated;grant select on public.rental_field_inspections,public.rental_field_inspection_items to authenticated;create policy rental_field_inspections_read on public.rental_field_inspections for select to authenticated using(exists(select 1 from public.rental_properties p where p.id=property_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_field_inspection_items_read on public.rental_field_inspection_items for select to authenticated using(exists(select 1 from public.rental_field_inspections i join public.rental_properties p on p.id=i.property_id where i.id=inspection_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_start_field_inspection(p_tenancy uuid,p_type text,p_items jsonb default '[]') returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;iid uuid;x jsonb;begin if auth.uid() is null or p_type not in('incoming','routine','outgoing','maintenance_follow_up') or jsonb_typeof(p_items)<>'array' then raise exception 'Valid inspection type and item list required';end if;select * into t from public.rental_tenancies where id=p_tenancy for update;if not found or not exists(select 1 from public.rental_properties p where p.id=t.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;insert into public.rental_field_inspections(organisation_id,property_id,unit_id,tenancy_id,inspection_type,started_by)values(t.organisation_id,t.property_id,t.unit_id,t.id,p_type,auth.uid())returning id into iid;for x in select value from jsonb_array_elements(p_items) loop if length(coalesce(x->>'key',''))>0 and length(coalesce(x->>'label',''))>0 then insert into public.rental_field_inspection_items(inspection_id,item_key,item_label,updated_by)values(iid,x->>'key',x->>'label',auth.uid());end if;end loop;return jsonb_build_object('inspection_id',iid,'status','in_progress');end$$;
create or replace function public.rental_record_field_inspection_item(p_item uuid,p_status text,p_note text default null,p_evidence text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare x public.rental_field_inspection_items%rowtype;begin if p_status not in('pass','attention','not_applicable') then raise exception 'Valid inspection item status required';end if;select * into x from public.rental_field_inspection_items where id=p_item for update;if not found or not exists(select 1 from public.rental_field_inspections i join public.rental_properties p on p.id=i.property_id where i.id=x.inspection_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;update public.rental_field_inspection_items set status=p_status,note=nullif(btrim(coalesce(p_note,'')),''),evidence_link=nullif(btrim(coalesce(p_evidence,'')),''),updated_by=auth.uid(),updated_at=now() where id=x.id;return jsonb_build_object('item_id',x.id,'status',p_status);end$$;
create or replace function public.rental_complete_field_inspection(p_inspection uuid,p_acknowledged_name text,p_signature_link text,p_summary text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare i public.rental_field_inspections%rowtype;begin if length(btrim(coalesce(p_acknowledged_name,'')))=0 or length(btrim(coalesce(p_signature_link,'')))=0 then raise exception 'Acknowledgement and signature evidence required';end if;select * into i from public.rental_field_inspections where id=p_inspection for update;if not found or not exists(select 1 from public.rental_properties p where p.id=i.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if exists(select 1 from public.rental_field_inspection_items where inspection_id=i.id and status='not_checked') then raise exception 'All inspection items must be checked before completion';end if;update public.rental_field_inspections set status='completed',completed_by=auth.uid(),completed_at=now(),acknowledged_by_name=btrim(p_acknowledged_name),signature_evidence_link=btrim(p_signature_link),summary_note=nullif(btrim(coalesce(p_summary,'')),'') where id=i.id;return jsonb_build_object('inspection_id',i.id,'status','completed');end$$;
revoke execute on function public.rental_start_field_inspection(uuid,text,jsonb),public.rental_record_field_inspection_item(uuid,text,text,text),public.rental_complete_field_inspection(uuid,text,text,text) from public,anon;grant execute on function public.rental_start_field_inspection(uuid,text,jsonb),public.rental_record_field_inspection_item(uuid,text,text,text),public.rental_complete_field_inspection(uuid,text,text,text) to authenticated;commit;
